import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1200, own='cte_123.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

H("865. d.1.A",3,"A practicum intern at a bottling plant is told the filler line keeps stopping. Before suggesting a fix, she lists when it stops, which station is involved and what changed that week. She is:","analyzing the elements of a problem",["ignoring the problem","assigning blame","ordering new equipment right away"],"Break a problem into parts first.")
H("865. d.1.A",4,"Which step belongs at the start of solving a recurring jam on a packaging line?","define the problem and gather facts about when and where it occurs",["replace every part","wait for the shift to end","blame the night crew"],"Define before fixing.")
H("865. d.1.B",3,"An intern finds two websites that give different torque values for the same fastener. Checking which one cites the manufacturer's manual is an example of:","judging the value of information critically",["copying the first result","trusting the longer page","picking the brighter site"],"Critical analysis checks the source.")
H("865. d.1.B",4,"Which source is most likely to give a trustworthy specification for a machine at the practicum site?","the equipment manufacturer's technical manual",["an anonymous forum post","a social media comment","a rumor from a coworker"],"Primary technical sources are reliable.")
H("865. d.1.C",3,"A practicum student reads a supplier datasheet, a safety data sheet and a trade journal article before recommending a coolant. This is:","technical research to gather information for decision making",["guessing a choice","avoiding the decision","delaying the task"],"Research supports decisions.")
H("865. d.1.C",4,"After collecting research on three coolants, the intern should next:","compare the findings against the plant's needs before deciding",["pick the cheapest without reading","discard all the notes","ask no one"],"Compare, then decide.")
H("865. d.2.A",3,"A crew leader admits her own mistake in a setup, thanks the operator who caught it and keeps a calm tone. Which leadership characteristics is she showing?","integrity and a positive attitude that build trust",["secrecy and blame","anger and pressure","favoritism"],"Honesty builds trust.")
H("865. d.2.A",4,"Team members follow a supervisor who keeps promises and shares credit. This best shows that trust is built through:","consistent honest actions",["loud commands","hidden plans","random decisions"],"Consistency builds trust.")
H("865. d.2.B",3,"Two interns on a pallet-wrapping task agree who loads, who wraps and who labels, then help each other finish early. This shows:","teamwork through cooperating to meet a shared goal",["working alone","competing for credit","avoiding the task"],"Cooperation achieves goals.")
H("865. d.2.B",4,"When a teammate is behind on a shared order, the best teamwork response is to:","offer help so the group goal is still met",["wait and watch","report only the delay","start a different job"],"Shared goals need shared effort.")
H("865. d.2.C",3,"Before a plant meeting ends, the facilitator asks everyone to voice concerns until the group agrees on one plan. This process is called:","building consensus",["voting by force","dictating","avoiding discussion"],"Consensus is group agreement.")
H("865. d.2.C",4,"A team that holds a short lunch together to welcome a new hire is engaged in:","team building",["payroll processing","equipment testing","inventory counting"],"Team building strengthens relationships.")
H("865. d.2.D",3,"On a group project, each practicum student completes the section assigned to them and also covers the cleanup rotation. They are demonstrating:","responsibility for shared group and individual tasks",["avoiding duties","passing blame","waiting to be told"],"Own your part.")
H("865. d.2.D",4,"If an individual task is left undone, the effect on the group is that:","the shared result may be delayed or lowered",["nothing changes","it improves quality","the group finishes sooner"],"Tasks depend on each other.")
H("865. d.2.E",3,"An intern greets coworkers by name, returns tools promptly and thanks the maintenance crew. This helps to:","establish and maintain effective working relationships",["create conflict","limit cooperation","avoid feedback"],"Respect builds relationships.")
H("865. d.2.E",4,"Which habit best keeps a working relationship strong after a disagreement over scheduling?","calmly discussing the issue and following through on what was agreed",["ignoring the person","gossiping about it","refusing to cooperate"],"Resolve respectfully.")
H("865. d.3.A",3,"A student tells the supervisor that the part needs to be chamfered, using the correct technical term instead of saying 'the edge thing.' This shows:","using technical vocabulary correctly",["using slang only","avoiding specifics","hiding information"],"Precise terms communicate clearly.")
H("865. d.3.A",4,"Why does using accurate vocabulary such as 'tolerance' and 'burr' matter on a shop floor?","it prevents misunderstandings that cause errors or injuries",["it makes meetings longer","it replaces measurements","it avoids reading manuals"],"Clear terms prevent mistakes.")
H("865. d.3.B",3,"A practicum student asks the toolroom clerk which drill bit size the job calls for, then repeats it back. She is using:","verbal skills to obtain and convey information",["only written skills","no skills","silence"],"Ask and confirm verbally.")
H("865. d.3.B",4,"When giving a shift handoff verbally, a worker should:","state key facts clearly and confirm the next worker understood",["rush through it","omit open issues","whisper to avoid questions"],"Confirm understanding.")
H("865. d.3.C",3,"An intern studies a vendor's website and a printed technical bulletin to learn how to calibrate a sensor. These are:","informational texts used for an occupation",["fictional novels","advertisements only","personal letters"],"Informational texts guide tasks.")
H("865. d.3.C",4,"Technical materials such as service bulletins are best used for:","finding procedures and specifications needed for the job",["entertainment","guessing","decoration"],"Bulletins hold procedures.")
H("865. d.3.D",3,"A student checks the author, date and publisher of a web page about welding codes before using it. She is:","evaluating the reliability of information",["ignoring details","guessing","copying blindly"],"Check the author and date.")
H("865. d.3.D",4,"An outdated web page about a safety standard is risky because:","the requirements may have changed since it was written",["outdated pages are always correct","all web pages are the same","dates never matter"],"Currency matters.")
H("865. d.3.E",3,"A supervisor crosses her arms and sighs while the intern explains a delay. The intern recognizes this may signal:","frustration, so he should explain more clearly and respectfully",["approval","no meaning","pride"],"Nonverbal cues carry meaning.")
H("865. d.3.E",4,"An intern who notices a coworker's confused expression during a training demo should:","pause and check whether the coworker needs the step explained again",["keep talking","walk away","laugh"],"Respond to cues.")
H("865. d.3.F",3,"During safety training, a student nods, takes notes and asks, 'So the guard stays in place until the lockout tag is applied?' She is applying:","active listening by clarifying information",["distracted listening","interrupting","ignoring the speaker"],"Clarify to confirm.")
H("865. d.3.F",4,"Which response shows active listening after a supervisor gives three instructions?","repeating the instructions in your own words to confirm them",["saying 'whatever'","checking your phone","walking off"],"Paraphrase to confirm.")
H("865. d.3.G",3,"An intern writes a clear incident summary and then explains it orally to the safety committee. She is using:","academic skills in written and oral communication",["no communication skills","only drawing","only guessing"],"Writing and speaking skills transfer to work.")
H("865. d.3.G",4,"A well-written work order includes:","what was done, which equipment was involved and the date",["only a signature","jokes","random notes"],"Clear records are complete.")
H("865. d.4.A",3,"A practicum student finds a supplier's catalog, checks that the part number matches the drawing and shares it with the buyer. She is using information literacy by:","accessing, evaluating and disseminating information",["hiding information","deleting records","guessing numbers"],"Find, check and share information.")
H("865. d.4.A",4,"Before passing on a spec sheet to the team, an intern should first:","verify that it is the current revision",["rewrite it from memory","print it without reading","keep it private"],"Evaluate before sharing.")
H("865. d.4.B",3,"A plant stores work orders, inspection logs and inventory counts in one system so the right people can find them. This is:","information management",["a lunch plan","a machine part","a safety sign"],"Organize and control information.")
H("865. d.4.B",4,"Good information management on a factory floor makes it easier to:","find accurate records quickly and avoid duplicated work",["lose files","hide data","slow communication"],"Organized data saves time.")
H("865. d.4.C",3,"At the end of each shift, an intern logs units produced, scrap counts and downtime in the plant's system. This is:","maintaining records to support ongoing operations",["wasting time","skipping documentation","copying a coworker's lunch order"],"Records help operations.")
H("865. d.4.C",4,"Why are accurate scrap records important to a manufacturing business?","they show where waste occurs so costs can be reduced",["they decorate reports","they replace inspections","they remove the need for planning"],"Data guides improvement.")
H("865. d.4.D",3,"A student writes 'run 200 clean parts without a rework by Friday' on her practicum plan. This is:","developing a goal",["avoiding planning","a complaint","a safety rule"],"Specific measurable goals help.")
H("865. d.4.D",4,"Which goal is the most specific and measurable?","reduce rework from 6 percent to 3 percent within one month",["do better","try harder","work faster sometime"],"SMART goals include numbers and a time.")
H("865. d.4.E",3,"An intern with a rush order, a safety walkthrough and routine cleanup lists them in order of urgency and importance. She is:","prioritizing tasks",["ignoring tasks","delaying all tasks","doing random tasks"],"Order by urgency and importance.")
H("865. d.4.E",4,"Which task should come first on a busy shift?","fixing a leaking hydraulic hose that creates a slipping hazard",["sorting old paperwork","organizing a shelf","rearranging labels"],"Safety hazards come first.")
H("865. d.4.F",3,"A student estimates two hours for setup, three for production and one for cleanup, then schedules them across the day. She is:","developing a timeline using time-management skills",["skipping planning","wasting time","avoiding a schedule"],"Timelines map tasks to time.")
H("865. d.4.F",4,"A good timeline for a multi-day practicum project should include:","start and end dates plus key checkpoints",["only the end date","no dates","only a title"],"Checkpoints keep projects on track.")
H("865. d.4.G",3,"A practicum team defines a project, plans the steps, carries them out, tracks progress and wraps up. These are phases of:","project management",["inventory counting","machine lubrication","safety training"],"Initiate, plan, execute, monitor, close.")
H("865. d.4.G",4,"In the monitor and control phase of a project, the team should:","compare progress with the plan and adjust as needed",["stop tracking","ignore the plan","start over without checking"],"Monitoring keeps the project on course.")
H("865. d.4.H",3,"An intern asks her supervisor to watch her set up a CNC fixture and rate her on accuracy and speed. This is:","evaluating proficiency in technical skills",["avoiding a task","reducing training","skipping practice"],"Self and supervisor evaluation of skills.")
H("865. d.4.H",4,"What is the best use of the results from a skills evaluation?","identify strengths and set goals to improve weak areas",["ignore the results","hide the weaknesses","avoid more practice"],"Use evaluation to grow.")
H("865. d.4.I",3,"A supervisor tells an intern her weld spacing is uneven. She thanks him, asks for an example and tries again. She is:","accepting critical feedback professionally",["arguing","ignoring him","quitting"],"Receive feedback constructively.")
H("865. d.4.I",4,"The most productive response to critical feedback from a supervisor is to:","listen, ask questions and apply the suggestions",["argue each point","avoid the supervisor","blame the equipment"],"Feedback is a tool for growth.")
H("865. d.5.A",3,"After eight weeks, an intern can set up a lathe alone, a task that needed full guidance in week one. This shows:","growth of technical skill competencies",["no change","a decline in skills","a lost task"],"Competence grows with practice.")
H("865. d.5.A",4,"Which evidence best shows growth in a technical skill during a practicum?","a series of inspection results that improve over time",["a single lucky result","a coworker's opinion only","a blank sheet"],"Document improvement.")
H("865. d.5.B",3,"A student earns a forklift certification during her practicum and logs the hours. This shows:","technical knowledge and skills demonstrated through earning a credential",["avoiding training","a class absence","a scheduling mistake"],"Credentials demonstrate skills.")
H("865. d.5.B",4,"A practicum activity that best demonstrates technical skills is:","completing a supervised task and being evaluated on it",["reading a poster","watching a break video","sorting mail"],"Hands-on evaluated tasks show competence.")
H("865. d.5.C",3,"At the end of the practicum, a student writes a one-page summary listing the main duties, key skills used and results achieved. This is:","an abstract of key points of the practicum",["a pay stub","a work order","an invoice"],"Abstracts summarize.")
H("865. d.5.C",4,"A good practicum abstract should be:","brief and focused on the most important points",["a long copy of every log","unrelated stories","a list of complaints"],"Abstracts are concise.")
H("865. d.5.D",3,"A student lists her machine operation, quality inspection and teamwork experience at the top of a one-page document for employers. This is a:","job-skills resume",["parking permit","work order","shift schedule"],"Resumes highlight skills.")
H("865. d.5.D",4,"What should a job-skills resume emphasize for a manufacturing technician position?","relevant technical skills, certifications and accomplishments",["favorite foods","unrelated hobbies only","unproven claims"],"Target the job.")
H("865. d.5.E",3,"An intern saves a photo of a finished fixture, an inspection report and a signed work order showing her contribution. She is:","collecting representative work samples",["destroying records","avoiding reviews","hiding work"],"Samples show real work.")
H("865. d.5.E",4,"A work sample from a practicum should be included only after the student:","checks that it contains no confidential company information",["adds private data","posts it online first","discards the original"],"Protect confidentiality.")
H("865. d.5.F",3,"A student keeps copies of her supervisor's written reviews and the industrial representative's feedback form in her binder. She is:","maintaining copies of practicum evaluations",["throwing away reviews","hiding reviews","sharing them with strangers"],"Keep evaluations for the portfolio.")
H("865. d.5.F",4,"Evaluations from a practicum supervisor are valuable in a portfolio because they:","provide outside evidence of the student's performance",["replace all records","are optional decoration","hide weaknesses"],"Third-party evidence adds credibility.")
H("865. d.5.G",3,"At a school event, a student walks a panel of local employers through her portfolio and answers questions. She is:","presenting the portfolio to interested stakeholders",["avoiding feedback","hiding work","skipping a presentation"],"Presenting showcases skills.")
H("865. d.5.G",4,"When presenting a portfolio to employers, a student should:","speak clearly, show evidence and be ready to answer questions",["read silently","avoid eye contact","skip the evidence"],"Prepare and engage.")
H("866.d.1.A",3,"An advanced practicum student explains a calibration step to a new hire using short sentences, a gesture to the gauge and a quick demonstration. This is:","clear, concise verbal and nonverbal communication",["confusing speech","silent avoidance","long rambling"],"Clear verbal and nonverbal communication.")
H("866.d.1.A",4,"Which message is the clearest handoff note for a night shift?","'Press 4 is down for a seal leak; parts arrive Tuesday; use Press 5.'",["'Stuff is broken.'","'You'll see.'","'Same as always.'"],"Specific, concise and actionable.")
H("866.d.1.B",3,"A student reviews a week of defect counts, spots that most occur on third shift and reports it with a simple chart. She is:","analyzing and communicating data effectively",["hiding data","avoiding charts","guessing causes"],"Analyze and present data clearly.")
H("866.d.1.B",4,"When presenting an observation about a machine's vibration to a supervisor, the student should:","give the measurements, the time they were taken and what changed",["say it feels off","skip the numbers","exaggerate"],"Include facts and context.")
H("866.d.1.C",3,"A supervisor frowns at a mislabeled box and says nothing. The practicum student correctly reads this as a sign that:","something needs correcting and she should ask what is wrong",["everything is perfect","she should ignore it","she should leave"],"Nonverbal cues carry meaning.")
H("866.d.1.C",4,"Which behavior best shows reading a coworker's nonverbal cues?","noticing hesitation and asking whether more explanation is needed",["talking louder","ignoring the pause","walking away"],"Respond to cues.")
H("866.d.1.D",3,"During a quality briefing, a student makes eye contact, avoids interrupting and summarizes the key points before asking questions. She is applying:","active listening",["distracted listening","talking over others","daydreaming"],"Active listening includes summarizing.")
H("866.d.1.D",4,"To confirm that she understood a complex work instruction, the student should:","restate the steps and ask whether she has them right",["nod without thinking","guess the details","skip the instruction"],"Clarify to avoid errors.")
H("866.d.2.A",3,"A student working on a fixture problem tries a plan alone, then tests it with a partner and revises it based on the results. She is employing:","critical-thinking skills independently and in a group",["random guessing","copying answers","avoiding thinking"],"Critical thinking works alone and in teams.")
H("866.d.2.A",4,"Which habit shows increasing fluency in critical thinking?","weighing evidence and alternatives before choosing a solution",["picking the first idea","avoiding questions","following without thinking"],"Evaluate options with evidence.")
H("866.d.2.B",3,"A scrap rate keeps climbing on a cutting line. The student separates the causes into material, tool wear and setup, then proposes a new tool-change interval. She is:","analyzing the elements of a problem to develop an innovative solution",["ignoring the data","blaming people","waiting for a failure"],"Break down, then create solutions.")
H("866.d.2.B",4,"A creative solution to reduce changeover time on a packaging line might be to:","stage tools and parts at the machine before the previous run ends",["slow the previous run","skip cleaning","remove safety steps"],"Prepare during runtime.")
H("866.d.2.C",3,"Before recommending a new sensor, the student reads the vendor spec, compares two models and interviews the maintenance lead. This is:","conducting technical research for a decision",["guessing a model","avoiding the decision","choosing by color"],"Research informs choices.")
H("866.d.2.C",4,"Which research source best answers whether a sensor suits a high-heat zone?","the manufacturer's temperature rating in the datasheet",["a coworker's guess","a photo of the sensor","a catalog price"],"Specs show limits.")
H("866.d.3.A",3,"A student reads the posted rule that machine guards stay in place during operation, and she consistently follows it even when no one is watching. She is:","demonstrating an understanding of and following workplace safety rules",["bending the rules","skipping training","ignoring policy"],"Follow rules consistently.")
H("866.d.3.A",4,"Why should safety rules be followed even when a task seems quick?","most injuries occur when shortcuts are taken",["rules waste time","only supervisors need them","injuries never happen"],"Shortcuts cause incidents.")
H("866.d.3.B",3,"A student cuts her finger on a burr. She stops, applies first aid, tells her supervisor and completes the incident form. She is following:","procedures for reporting and handling accidents",["hiding the injury","waiting a week","ignoring the form"],"Report promptly.")
H("866.d.3.B",4,"Why must even minor accidents and near-misses be reported?","reports reveal hazards that can be fixed before someone is seriously hurt",["to assign blame","to avoid training","to save paper"],"Near-miss reporting prevents injuries.")
H("866.d.4.A",3,"A student arrives on time, follows the supervisor's instructions on the day's tasks and finishes them without being reminded. She is demonstrating:","a positive, productive work ethic",["a poor attitude","avoidance","laziness"],"Reliability shows work ethic.")
H("866.d.4.A",4,"Which behavior best reflects a strong work ethic during a slow shift?","finding useful tasks such as cleaning and restocking without being asked",["checking a phone","sitting idle","leaving early"],"Initiative shows work ethic.")
H("866.d.4.B",3,"A student sees a coworker pencil-whip an inspection record to save time. She weighs the risk to customers and reports the issue to the supervisor. She is:","applying ethical reasoning to make a decision",["staying silent","joining in","ignoring the facts"],"Ethical reasoning considers consequences.")
H("866.d.4.B",4,"An ethical decision in a manufacturing job is best made by considering:","honesty, safety and the effects on others",["only personal gain","what is easiest","what others will not see"],"Weigh honesty and impact.")
H("866.d.4.C",3,"A student follows environmental rules for disposing of used cutting fluid and wears required PPE every time. She is:","complying with applicable rules, laws and regulations",["avoiding rules","breaking policy","skipping PPE"],"Compliance means consistent follow-through.")
H("866.d.4.C",4,"Failing to follow applicable regulations at a plant may result in:","fines, injuries and loss of the company's ability to operate",["higher bonuses","a safer workplace","no consequences"],"Noncompliance has consequences.")
H("866.d.5.A",3,"A student logs the tasks she performed on the supervised line, notes what went well and what to improve and gets a supervisor sign-off. She is:","conducting, documenting and evaluating learning activities",["avoiding documentation","hiding her work","skipping evaluation"],"Do, document, evaluate.")
H("866.d.5.A",4,"A learning log entry is most useful when it includes:","the task, the result and what she learned",["only the date","no details","jokes"],"Record outcomes and lessons.")
H("866.d.5.B",3,"Working beside a senior technician, a student learns to read a servo drive display and adjust parameters under supervision. She is:","developing advanced technical knowledge and skills related to her occupation",["avoiding training","repeating basics only","skipping the display"],"Advanced skills develop with guided practice.")
H("866.d.5.B",4,"Which activity best develops advanced technical skills in a manufacturing practicum?","completing progressively harder tasks with supervisor feedback",["repeating the easiest task only","avoiding feedback","watching only"],"Progress with feedback.")
H("866.d.5.C",3,"At week 4 a student needed help to set a press brake; at week 12 she does it alone and passes inspection. This shows:","growth of her technical skill competencies",["a decline in skill","no change","a scheduling error"],"Competence grows.")
H("866.d.5.C",4,"The strongest evidence of competency growth is:","repeatable independent performance that meets quality standards",["a lucky first try","hearing praise once","a single guess"],"Consistent independent results.")
H("866.d.5.D",3,"A student scores herself high on welding but low on blueprint reading and asks to practice reading prints. She is:","evaluating strengths and weaknesses in technical skill proficiency",["ignoring her weaknesses","avoiding practice","hiding her scores"],"Honest self-evaluation directs growth.")
H("866.d.5.D",4,"After identifying a weakness in measuring tools, the next best step is to:","set a goal and practice with feedback until it improves",["avoid measuring","hide the weakness","rely on others forever"],"Plan to improve.")
H("866.d.5.E",3,"A student gathers pictures of finished parts, inspection reports with her initials and her supervisor's evaluation for her end-of-term review. She is:","collecting representative work samples",["discarding evidence","hiding results","losing records"],"Samples show growth.")
H("866.d.5.E",4,"Which item makes the most convincing work sample for a machining practicum?","an inspected part with its measurement report and a supervisor note",["a blank form","an unlabeled photo","a rumor"],"Verified evidence is persuasive.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_123.jsonl"))
